// Electron's build packages `static/` next to the bundle; Tauri only serves dist-tauri/,
// so copy it there (locales are generated by webpack and the web-only files are not needed).
import { cpSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const skip = new Set(['locales', 'pwabuilder-sw.js', 'manifest.json'])

cpSync(join(root, 'static'), join(root, 'dist-tauri/static'), {
  recursive: true,
  filter: (source) => {
    const relative = source.slice(join(root, 'static').length + 1)
    return !skip.has(relative.split('/')[0])
  }
})
